function openActions(p){if(sold(p))return;actionProduct=p;var box=$('actionChoices');clear(box);$('actionTitle').textContent=p.name;var normal=el('button','1 Stück · '+money(p.price),'wide');normal.onclick=function(){closeActions();add(p);};append(box,normal);actions(p).forEach(function(a){var b=el('button',a.name+' · '+money(a.price),'wide primary'),detail=el('p',a.units+' Stück'+(a.cups?' · '+a.cups+' Becher mit Einsatz':''),'muted');b.onclick=function(){closeActions();addAction(p,a);};append(box,b,detail);});toggle($('actionOverlay'),'hidden',false);}
