var sale=$('sale'),tracked=null,timer=null,suppress=null,suppressAt=0,mouse=null,mtimer=null,touchAt=0;
function btn(n){while(n&&n!==sale){if(n.tagName&&n.tagName.toUpperCase()==='BUTTON')return n;n=n.parentNode;}return null;}
function cancelTouch(){if(timer!==null)clearTimeout(timer);timer=null;tracked=null;}
