sale.addEventListener('touchstart',function(e){touchAt=Date.now();cancelTouch();cancelMouse();var b=btn(e.target),p=e.changedTouches&&e.changedTouches[0];if(!b||b.disabled||!p||e.touches.length!==1)return;tracked={b:b,x:p.clientX,y:p.clientY,id:p.identifier,long:false};if(b._promoProduct)timer=setTimeout(function(){if(!tracked)return;tracked.long=true;suppressClick(b);openActions(b._promoProduct);},500);},false);
