document.addEventListener('mousemove',function(e){if(mouse&&(Math.abs(e.clientX-mouse.x)>10||Math.abs(e.clientY-mouse.y)>10))cancelMouse();},false);
document.addEventListener('mouseup',function(){if(mouse&&suppress===mouse.b)suppressClick(mouse.b);cancelMouse();},false);
sale.addEventListener('contextmenu',function(e){var b=btn(e.target);if(!b||!b._promoProduct)return;e.preventDefault();cancelMouse();if(tracked){tracked.long=true;if(timer!==null)clearTimeout(timer);timer=null;}suppressClick(b);openActions(b._promoProduct);},false);
