Object.keys(featuredColors).forEach(function(k){palette[k]=featuredColors[k];drinkIcons[k]=featuredIcons[k];});
function featuredPalette(products){return products.map(function(p){var k=String(p.name||'').trim().toLowerCase();return featuredColors[k]&&(!p.color||colorValue(p.color)==='#852f3b')?copy(p,{color:featuredColors[k]}):p;});}

function standardColor(name){return palette[String(name||'').trim().toLowerCase()]||'#852f3b';}
function newColors(products){return products.map(function(p){return copy(p,{color:!p.color||colorValue(p.color)==='#852f3b'?standardColor(p.name):colorValue(p.color)});});}
function prefs(){var p=data.prefs||{};return {dark:!!p.dark,addCash:p.addCash!==false,notes:Array.isArray(p.notes)&&p.notes.length?p.notes:[500,1000,2000,5000,10000],wake:!!p.wake,productImages:p.productImages!==false};}
function parked(){return Array.isArray(data.parked)?data.parked:[];}
function sold(p){return !!(data.soldOut&&data.soldOut[p.id]);}

var padTarget='',padEntry='',padReplace=false,padReturn=null;
function cleanTip(n){return integer(n,0,100000000)?n:0;}
function canTip(){return actualOrder()&&baseDue()>0;}
function tipLimit(){var r=cents($('cash').value);return canTip()&&r!==null?r-baseDue():-1;}
function closePad(restoreFocus){if(!padTarget)return;var ret=padReturn;padTarget='';padEntry='';padReplace=false;padReturn=null;toggle($('numberOverlay'),'hidden',true);if(restoreFocus&&ret&&ret.focus)ret.focus();}
function closeTip(){if(padTarget==='tip')closePad(false);toggle($('tipPanel'),'hidden',true);$('tipToggle').setAttribute('aria-expanded','false');}
function tipSuggestions(base,received){if(base<=0||received===null||received<=base)return [];var values=[100,500,1000].map(function(step){return (Math.floor(base/step)+1)*step;});for(var i=2;i<=4;i++)values.push((Math.floor(base/500)+i)*500);return values.filter(function(n,i,a){return n<=received&&a.indexOf(n)===i;}).sort(function(a,b){return a-b;}).slice(0,3);}
function updateTip(){if(!canTip()){tip=0;closeTip();}$('tipToggle').disabled=!canTip();toggle($('tipRow'),'hidden',!tip);$('tipSum').textContent=money(tip);if(!$('tipPanel').classList.contains('hidden')){var enough=tipLimit()>0;$('tipKeep').disabled=!enough;$('tipCustom').disabled=!enough;$('tipHelp').textContent=enough?'Verfügbar für Trinkgeld: '+money(tipLimit()):'Zuerst ausreichend Bargeld erfassen.';tipOptions();}}
function setTip(n){if(!canTip()||!integer(n,0,100000000)||n>tipLimit())return false;tip=n;closePad(false);closeTip();render();return true;}
function tipOptions(){var root=$('tipQuick');clear(root);var base=baseDue(),values=tipSuggestions(base,cents($('cash').value));values.forEach(function(n){var k=el('button',undefined,'tip-choice'),t=n-base;append(k,el('b',money(n)),el('small','+'+money(t)+' Trinkgeld'));k.setAttribute('aria-label','Auf '+money(n)+' aufrunden, '+money(t)+' Trinkgeld');k.onclick=function(){setTip(n-baseDue());};append(root,k);});toggle(root,'hidden',!values.length);}
$('tipToggle').onclick=function(){if(!canTip())return;if(!$('tipPanel').classList.contains('hidden')){closeTip();return;}toggle($('tipPanel'),'hidden',false);$('tipToggle').setAttribute('aria-expanded','true');updateTip();};
$('tipKeep').onclick=function(){var n=tipLimit();if(n>0)setTip(n);};
$('tipClear').onclick=function(){tip=0;closeTip();render();};
function padValue(){return cents(padEntry);}
function padRefresh(){var n=padValue(),d=due(),r=cents($('cash').value),t=padTarget==='tip'&&n!==null?n-baseDue():null,ok=n!==null,msg='',preview='';
$('numberValue').textContent=(padEntry||'0,00')+' €';
toggle($('numberValue'),'replace-ready',padReplace);
if(padTarget==='tip'){ok=ok&&canTip()&&t>=0&&t<=tipLimit();if(n!==null&&!ok)msg=n<baseDue()?'Mindestens '+money(baseDue())+'.':'Maximal '+money(Math.max(0,r||0))+'.';if(ok)preview='Trinkgeld: '+money(t)+' · Retourgeld: '+money(r-baseDue()-t);}
else if(n!==null){preview=n>=d?'Retourgeld: '+money(n-d):'Geld fehlt noch: '+money(d-n);if(tip&&n<d)msg='Das gewählte Trinkgeld ist noch nicht gedeckt.';}
$('numberPreview').textContent=preview;$('numberError').textContent=msg;$('numberOK').disabled=!ok;}
function openPad(target,ret){if(target==='tip'&&tipLimit()<=0)return;if(target==='cash'&&(!actualOrder()||due()<=0))return;padTarget=target;padReturn=ret;var existing=target==='cash'?cents($('cash').value):null;padEntry=existing===null?'':dec(existing);padReplace=existing!==null;$('numberTitle').textContent=target==='cash'?'Geld erhalten':'Gesamtbetrag inkl. Trinkgeld';$('numberContext').textContent=target==='cash'?'Zu bezahlen: '+money(due()):'Rechnung: '+money(baseDue())+' · Erhalten: '+money(cents($('cash').value)||0);toggle($('numberOverlay'),'hidden',false);padRefresh();if($('numberCancel').focus)$('numberCancel').focus();}
function padKey(k){if(!padTarget)return;if(k==='clear'){padEntry='';padReplace=false;}else if(k==='back'){padEntry=padReplace?'':padEntry.slice(0,-1);padReplace=false;}else{if(padReplace){padEntry='';padReplace=false;}if(k===','||k==='.'){if(padEntry.indexOf(',')<0)padEntry=(padEntry||'0')+',';}else if(/^[0-9]$/.test(k)){if(padEntry==='0')padEntry='';var parts=padEntry.split(',');if(parts.length===2&&parts[1].length>=2){padRefresh();return;}var next=padEntry+k;if(next.length<=10&&cents(next)!==null)padEntry=next;}}padRefresh();}
function applyPad(){if(!padTarget||$('numberOK').disabled)return;var n=padValue(),target=padTarget;if(n===null)return;if(target==='tip'){if(setTip(n-baseDue())&&$('tipToggle').focus)$('tipToggle').focus();}else{closePad(true);$('cash').value=dec(n);renderCash();}}
$('cashOpen').onclick=function(){openPad('cash',this);};
$('tipCustom').onclick=function(){openPad('tip',this);};
$('numberCancel').onclick=function(){closePad(true);};
$('numberOK').onclick=applyPad;
$('numberClear').onclick=function(){padKey('clear');};
$('numberOverlay').onclick=function(e){if(e.target===this)closePad(true);};
function initNumberPad(){var root=$('numberKeys');['7','8','9','4','5','6','1','2','3',',','0','back'].forEach(function(k){var b=el('button',k==='back'?'⌫':k);if(k==='back')b.setAttribute('aria-label','Letzte Ziffer löschen');b.onclick=function(){padKey(k);};append(root,b);});document.addEventListener('keydown',function(e){if(!padTarget)return;var k=e.key||'',code=e.keyCode||e.which;if(!k){if(code>=48&&code<=57)k=String(code-48);else if(code>=96&&code<=105)k=String(code-96);else if(code===188||code===190||code===110)k=',';else if(code===8)k='Backspace';else if(code===46)k='Delete';else if(code===13)k='Enter';else if(code===27)k='Escape';}if(e.ctrlKey||e.altKey||e.metaKey)return;if(/^[0-9.,]$/.test(k)){e.preventDefault();padKey(k);}else if(k==='Backspace'||k==='Delete'){e.preventDefault();padKey(k==='Backspace'?'back':'clear');}else if(k==='Escape'){e.preventDefault();closePad(true);}else if(k==='Enter'){e.preventDefault();applyPad();}else if(k==='Tab'){var bs=$('numberOverlay').getElementsByTagName('button'),enabled=[];for(var i=0;i<bs.length;i++)if(!bs[i].disabled)enabled.push(bs[i]);if(enabled.length){var pos=enabled.indexOf(document.activeElement),next=e.shiftKey?(pos<=0?enabled.length-1:pos-1):(pos<0||pos===enabled.length-1?0:pos+1);e.preventDefault();enabled[next].focus();}}},false);}

var finishing=false,successTimer=null,cashFeedbackTimer=null,drinkFeedbackTimer=null;
function showCashFeedback(n,additive){var e=$('cashFeedback');e.textContent=(additive?'+':'= ')+money(n);if(cashFeedbackTimer!==null)clearTimeout(cashFeedbackTimer);cashFeedbackTimer=setTimeout(function(){e.textContent='';},900);}
function showDrinkFeedback(name){var e=$('drinkFeedback');e.textContent='✓ '+name;if(drinkFeedbackTimer!==null)clearTimeout(drinkFeedbackTimer);drinkFeedbackTimer=setTimeout(function(){e.textContent='';},800);}
function clearFeedback(){if(cashFeedbackTimer!==null)clearTimeout(cashFeedbackTimer);if(drinkFeedbackTimer!==null)clearTimeout(drinkFeedbackTimer);$('cashFeedback').textContent='';$('drinkFeedback').textContent='';}
function showSuccess(tx){var box=$('saleSuccess');$('successTitle').textContent=testMode?'Testverkauf abgeschlossen':tx.total<0?'Pfandrückgabe abgeschlossen':'Verkauf abgeschlossen';$('successLabel').textContent=tx.total<0?'Auszahlung':tx.change?'Retourgeld':'Kein Retourgeld';$('successAmount').textContent=money(tx.change);toggle(box,'hidden',false);if(successTimer!==null)clearTimeout(successTimer);successTimer=setTimeout(function(){toggle(box,'hidden',true);},2000);}
var categoryKeys=['products','device','payment','security','recent','template','backup','diagnosis','test'];
function setCategory(k,open){var panel=$('body-'+k),button=$('cat-'+k);toggle(panel,'hidden',!open);button.setAttribute('aria-expanded',String(open));if(k==='recent'&&open)renderRecent();if(k==='diagnosis'&&open){showDiagnosis();refreshUpdatePanel();}if(k==='backup'&&open)refreshBackupStamp();}
function initCategories(){categoryKeys.forEach(function(k){$('cat-'+k).onclick=function(){setCategory(k,$('body-'+k).classList.contains('hidden'));};});}
function closeCategories(){categoryKeys.forEach(function(k){setCategory(k,false);});}

function currentDraft(){return {q:copy(q,{}),aq:copy(aq,{}),out:out,back:back,tip:tip,cash:$('cash').value};}
function assignDraft(d){closePad(false);q=copy(d.q||{},{});aq=copy(d.aq||{},{});out=d.out||0;back=d.back||0;tip=cleanTip(d.tip);closeTip();$('cash').value=d.cash||'';}
function configBlocked(){return hasOrder()||parked().length>0||testMode;}
function renderCashKeys(){var root=$('cashkeys');clear(root);prefs().notes.forEach(function(n){var k=el('button',dec(n).replace(/,00$/,'')+' €','note-'+(n/100));k.onclick=function(){var current=cents($('cash').value);if(prefs().addCash&&current===null&&$('cash').value.trim()){message('Bitte gültigen Geldbetrag eingeben.',true);return;}var amount=prefs().addCash?(current||0)+n:n;if(amount>100000000){message('Geldbetrag zu hoch.',true);return;}$('cash').value=dec(amount);renderCash();showCashFeedback(n,prefs().addCash);};append(root,k);});}
$('clearCash').onclick=function(){$('cash').value='';renderCash();};
